def _require_company_staff_access(write_access: bool = False):
    async def _dependency(request: Request, json_body: dict, worker_key_valid: bool = Depends(require_worker_key)):
        if worker_key_valid:
            # Worker key bypasses all other checks
            return

        claims = decode(_bearer(request), "access")
        if claims is None:
            raise HTTPException(status_code=401, detail="Session expired or invalid")

        requested_company_id = json_body.get("companyId")
        if not isinstance(requested_company_id, int):
            raise HTTPException(status_code=400, detail="companyId must be an integer in the request body")

        user_has_access_to_company = False
        user_roles_for_company = []

        for company_info in claims.get("companies", []):
            if company_info.get("companyId") == requested_company_id:
                user_has_access_to_company = True
                user_roles_for_company.append(str(company_info.get("role", "")).strip().lower())
                break  # Found the relevant company for the user

        if not user_has_access_to_company:
            raise HTTPException(status_code=403, detail=f"Forbidden: User not authorized for company {requested_company_id}")

        if write_access:
            if "admin" not in user_roles_for_company and "manager" not in user_roles_for_company:
                raise HTTPException(status_code=403, detail="Forbidden: Requires Admin or Manager role for write operations")
