{"api_file": {"path": "src/api/prepaidWalletApi.ts", "content": "import { notifyDataChanged } from '../utils/refreshBus';

const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface PrepaidWallet {
  prepaidWalletEntryId: number;
  companyId: number;
  clientId: number;
  entryType: 'TOPUP' | 'USAGE' | 'POS_SALE' | 'REFUND' | 'REVERSAL' | 'ADJUSTMENT' | 'OPENING_BALANCE';
  direction: 'C' | 'D'; // 'C' for Credit, 'D' for Debit
  amountMXN: number;
  balanceAfter: number;
  idempotencyKey: string;
  source?: string;
  referenceType?: string;
  referenceId?: number;
  createdByUserId?: number;
  note?: string;
  created_At: string; // ISO date string
  updated_at?: string; // ISO date string
  client_first_name?: string;
  client_last_name?: string;
}

export interface PrepaidWalletListResponse {
  prepaidWallets: PrepaidWallet[];
}

export interface PrepaidWalletBalanceResponse {
  availableBalance: number;
}

// GET ALL prepaid wallet entries
export async function getAllPrepaidWallets(companyId: number, clientId?: number, entryType?: string): Promise<PrepaidWallet[]> {
  const payload: { companyId: number; clientId?: number; entryType?: string } = { companyId };
  if (clientId) payload.clientId = clientId;
  if (entryType) payload.entryType = entryType;

  const res = await fetch(BASE_URL + "/all_prepaidWallets", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "prepaidWallets": [payload] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: PrepaidWalletListResponse = await res.json();
  return data.prepaidWallets ?? [];
}

// GET client's prepaid wallet balance
export async function getPrepaidWalletBalance(companyId: number, clientId: number): Promise<PrepaidWalletBalanceResponse> {
  const res = await fetch(BASE_URL + "/prepaidWallets/balance", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ companyId, clientId }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}
