import { useIonViewWillEnter } from '@ionic/react';
import { useUser } from '../../../contexts/UserContext';
import { useToast } from '../../../hooks/useToast';
import { onDataChanged, notifyDataChanged } from '../../../utils/refreshBus';
import { getAllPrepaidWallets, getPrepaidWalletBalance, PrepaidWallet } from '../../../api/prepaidWalletApi';
import { SearchbarInputEventDetail, SelectChangeEventDetail, RefresherEventDetail } from '@ionic/core';

const PAGE_SIZE = 20;

export const usePrepaidWallet = () => {
  const { companyId, clientId: userClientId } = useUser(); // userClientId can be used if page is client-specific
  const { showToast, toastProps } = useToast();
  const [allEntries, setAllEntries] = useState<PrepaidWallet[]>([]);
  const [displayedEntries, setDisplayedEntries] = useState<PrepaidWallet[]>([]);
  const [balance, setBalance] = useState<number>(0);
  const [initialLoading, setInitialLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [currentPage, setCurrentPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);

  // Filters
  const [searchText, setSearchText] = useState('');
  const [selectedEntryType, setSelectedEntryType] = useState<PrepaidWallet['entryType'] | ''>('');

  const loadAllData = useCallback(async (refresh = false) => {
    if (refresh) {
      setInitialLoading(true);
      setCurrentPage(0);
      setHasMore(true);
      setAllEntries([]);
      setDisplayedEntries([]);
    }

    try {
      const fetchedEntries = await getAllPrepaidWallets(companyId, userClientId, selectedEntryType === '' ? undefined : selectedEntryType);
      setAllEntries(fetchedEntries.sort((a, b) => new Date(b.created_At).getTime() - new Date(a.created_At).getTime())); // Newest first
      setBalance(0); // Reset balance, load separately
      if (userClientId) {
        const balanceResponse = await getPrepaidWalletBalance(companyId, userClientId);
        setBalance(balanceResponse.availableBalance);
      }
    } catch (err) {
      showToast((err as Error).message ?? 'Error desconocido al cargar movimientos', 'danger');
      setAllEntries([]);
      setBalance(0);
    } finally {
      setInitialLoading(false);
      setLoadingMore(false);
    }
  }, [companyId, userClientId, selectedEntryType, showToast]);

  // Effect to load initial data and update displayed entries when allEntries changes
  useEffect(() => {
    if (!initialLoading) {
      setDisplayedEntries(allEntries.slice(0, PAGE_SIZE));
      setHasMore(allEntries.length > PAGE_SIZE);
      setCurrentPage(0);
    }
  }, [allEntries, initialLoading]);

  // Initial load and re-entry load
  useEffect(() => { loadAllData(); }, [loadAllData]);
  useIonViewWillEnter(() => { loadAllData(); });
  useEffect(() => onDataChanged(() => loadAllData()), [loadAllData]);

  const loadMoreItems = useCallback(() => {
    if (loadingMore || !hasMore) return;

    setLoadingMore(true);
    const nextPage = currentPage + 1;
    const newDisplayedCount = (nextPage + 1) * PAGE_SIZE;
    setDisplayedEntries(allEntries.slice(0, newDisplayedCount));
    setCurrentPage(nextPage);
    setHasMore(newDisplayedCount < allEntries.length);
    setLoadingMore(false);
  }, [loadingMore, hasMore, allEntries, currentPage]);

  const handleRefresh = useCallback(async (event: CustomEvent<RefresherEventDetail>) => {
    await loadAllData(true);
    event.detail.complete();
  }, [loadAllData]);

  const filteredItems = useMemo(() => {
    if (!searchText && selectedEntryType === '') return displayedEntries;

    return displayedEntries.filter(entry => {
      const matchesSearchText = searchText
        ? (`${entry.client_first_name} ${entry.client_last_name}`.toLowerCase().includes(searchText.toLowerCase()) ||
           entry.note?.toLowerCase().includes(searchText.toLowerCase()))
        : true;

      const matchesEntryType = selectedEntryType !== ''
        ? entry.entryType === selectedEntryType
        : true;

      return matchesSearchText && matchesEntryType;
    });
  }, [displayedEntries, searchText, selectedEntryType]);

  return {
    items: allEntries, // All items fetched (up to backend limit)
    filteredItems,     // Items displayed after client-side filtering
    balance,
    initialLoading,
    loadingMore,
    toastProps,
    hasMore,
    loadMoreItems,
    handleRefresh,
    searchText,
    setSearchText,
    selectedEntryType: selectedEntryType as PrepaidWallet['entryType'] | '',
    setSelectedEntryType: setSelectedEntryType as (value: PrepaidWallet['entryType'] | '') => void,
  };
};

export type PrepaidWalletVM = ReturnType<typeof usePrepaidWallet>;
